extension OPLBank {
    /// The Fat Man's General MIDI instruments for the FM chip, as Windows 95 and 98 played MIDI files
    /// on a Sound Blaster 16's OPL3: 128 melodic instruments by program, and the percussion by note,
    /// each of two operators, with deep tremolo and vibrato.
    static let fatMan: OPLBank = {
        var timbres = [
            // What libADLMIDI's channels hold before they are given an instrument.
            OPLTimbre(modulatorE862: 0x155_7403, carrierE862: 0x005_B381, modulator40: 0x49, carrier40: 0x80, feedconn: 0x4, noteOffset: 0),
            // The empty instrument's.
            OPLTimbre(modulatorE862: 0, carrierE862: 0, modulator40: 0, carrier40: 0, feedconn: 0, noteOffset: 0),
            OPLTimbre(modulatorE862: 0, carrierE862: 0, modulator40: 0, carrier40: 0, feedconn: 0, noteOffset: 0),
        ]
        var instruments: [OPLInstrument] = []
        let data = fatManData
        for index in 0 ..< data.count / 19 {
            let at = index * 19
            func e862(_ from: Int) -> UInt32 {
                UInt32(data[from + 4]) << 24 | UInt32(data[from + 3]) << 16 | UInt32(data[from + 2]) << 8 | UInt32(data[from])
            }
            timbres.append(OPLTimbre(modulatorE862: e862(at + 10), carrierE862: e862(at + 5), modulator40: data[at + 11],
                                     carrier40: data[at + 6], feedconn: data[at + 4], noteOffset: Int8(bitPattern: data[at + 1])))
            let timbre = timbres.count - 1
            instruments.append(OPLInstrument(timbres: (timbre, timbre), drumTone: data[at + 3], flags: data[at],
                                             soundKeyOnMs: UInt16(data[at + 15]) | UInt16(data[at + 16]) << 8,
                                             soundKeyOffMs: UInt16(data[at + 17]) | UInt16(data[at + 18]) << 8,
                                             midiVelocityOffset: Int8(bitPattern: data[at + 2]), voice2FineTune: 0))
        }
        return OPLBank(timbres: timbres, melodic: Array(instruments[0 ..< 128]), percussion: Array(instruments[128 ..< 256]),
                       deepTremolo: true, deepVibrato: true)
    }()

